UPDATE work_order SET business_no=#{businessNo},owner_user_id=#{ownerUserId},owner_binding_status=#{binding},
  status='PENDING_DISPATCH',status_started_at=#{now},updated_by=#{actorId},updated_at=#{now},version=version+1
WHERE id=#{id} AND status='DRAFT' AND version=#{version}

UPDATE work_order SET status=#{toStatus},status_started_at=#{now},updated_by=#{actorId},updated_at=#{now},version=version+1,
  shop_id=NULLshop_id=#{shopId}shop_id=shop_id
WHERE id=#{id} AND status=#{fromStatus} AND version=#{version}
